            if(cached==Integer.MIN_VALUE){diagPacket(viewer,0);out.writeByte(0);snapshot(out,this,0,viewer);return;}
            if(viewer.live){diagPacket(viewer,5);out.writeByte(5);snapshot(out,this,revision,viewer);return;}
