        Path base=publicRoot(),file=base.resolve(relative).normalize();if(!file.startsWith(base)||!Files.isRegularFile(file)){x.sendResponseHeaders(404,-1);x.close();return;}
        String type=path.endsWith(".html")?"text/html; charset=utf-8":path.endsWith(".jad")?"text/vnd.sun.j2me.app-descriptor; charset=utf-8":path.endsWith(".jar")?"application/java-archive":path.endsWith(".png")?"image/png":path.endsWith(".jpg")?"image/jpeg":path.endsWith(".pdf")?"application/pdf":path.endsWith(".sis")?"application/vnd.symbian.install":"application/zip";
