    static String validRoomName(String name){name=name.trim();if(name.isEmpty()||name.length()>32||name.chars().anyMatch(c->c<32))throw new IllegalArgumentException("Tên phòng từ 1 đến 32 ký tự.");return name;}
    static boolean legacyWeapon(int id){return id==0||id==3||id==5||id==9;}
    static boolean validWeapon(int id){return ShopCatalog.weapon(id);}
    static boolean hasWeapon(CloudStore.Profile profile){return validWeapon(profile.equipped)&&(profile.owned&(1<<profile.equipped))!=0&&(profile.wornMask&1)!=0;}
    static void requireWeapon(Session player){if(!hasWeapon(player.profile))throw new IllegalArgumentException("Bạn cần trang bị vũ khí trước khi vào phòng đấu.");}
    static String validName(String value){value=value.trim();if(value.isEmpty()||value.length()>13||value.chars().anyMatch(c->c<32))throw new IllegalArgumentException("Tên từ 1 đến 13 ký tự.");return value;}
