    void leave(Session s){Room r=rooms.get(s.room);s.room=0;s.held=0;s.armed=false;if(r!=null)synchronized(r){Room home=r.returnRooms.remove(s);if(home!=null)synchronized(home){int seat=home.slot(s);if(seat>=0)home.members[seat]=null;if(home.host==s)for(Session peer:home.members)if(peer!=null){home.host=peer;break;}}for(int i=0;i<r.count;i++)if(r.members[i]==s)r.members[i]=null;if(r.phase==0){if(r.host==s){rooms.remove(r.id);for(Session m:r.members)if(m!=null&&m.room==r.id)m.room=0;}else r.refreshWaiting();}else{r.departed(s);for(int i=0;i<r.count;i++)if(r.avatars[i].owner==s){r.avatars[i].owner=null;r.avatars[i].bot=true;}}}}
    static void equipmentState(DataOutputStream out,Session s)throws IOException{if(s.equipment){out.writeInt(s.profile.shoppingMoney);out.writeByte(s.profile.wornMask);}for(int mask:s.profile.wardrobe)out.writeShort(mask);if(s.bagLayout){out.writeShort(175);for(int cell:s.profile.bagLayout)out.writeShort(cell);}if(s.expansion)Expansion780.write(out,s.profile);}
