        for(int i=0;i<r.count;i++){Battle.Unit u=b.units[i];for(int v:new int[]{u.x,u.y,u.vy,u.hp,u.energy,u.rage,u.angle,(replay||r.controls(viewer,i))?u.power:0,u.face,u.walk,u.weapon,u.attackTicks,u.slope,u.heals,u.deathX,u.deathY,r.controls(viewer,i)?u.lastPower:-1,r.controls(viewer,i)?u.pendingPower:-1,(viewer.itemFx||u.lastBuff<11)?u.flashTicks:0,u.landingTicks,(viewer.itemFx||u.lastBuff<11)?u.lastBuff:0})out.writeShort(v);out.writeBoolean(u.dead);if(viewer.actors)out.writeInt(u.experience);if(viewer.expansion){out.writeShort(u.forgeAttack);out.writeShort(u.forgeDefense);out.writeShort(u.forgeLuck);out.writeByte(u.npc);out.writeShort(u.maxHp);out.writeShort(u.maxEnergy);out.writeShort(u.attackBonus);out.writeShort(u.forgeWeaponBonus);for(int bonus:u.weaponForge)out.writeShort(bonus);}}
        out.writeByte(b.ballCount);for(int i=0;i<b.ballCount;i++){Battle.Ball ball=b.balls[i];for(int v:new int[]{ball.x,ball.y,ball.vx,ball.vy})out.writeInt(v);out.writeByte(ball.owner);out.writeShort(ball.age);out.writeByte(ball.weapon);out.writeBoolean(ball.fly);out.writeBoolean(ball.powered);}
